@triton.jit
def _clamp_sqrt_kernel(eigenvalues, output, n_elements, BLOCK_SIZE: tl.constexpr):
    offsets = tl.program_id(0) * BLOCK_SIZE + tl.arange(0, BLOCK_SIZE)
    mask = offsets < n_elements
    values = tl.load(eigenvalues + offsets, mask=mask, other=0.0)
    result = tl.sqrt(tl.maximum(values, 0.0))
    tl.store(output + offsets, result, mask=mask)


@libentry()
@triton.jit
def _sqrt_reconstruct_kernel(
    eigenvectors,
    eigenvalues,
    output,
    n,
    stride_batch,
    stride_row,
    stride_col,
    BLOCK_N: tl.constexpr,
):
    """Reconstruct V sqrt(L) V^H for one batch element in a single launch.

    Real inputs only, so V^H is a plain transpose.  ``BLOCK_N`` (a power of two
    >= n) zero-pads both operands, which keeps the padded lanes out of the
    reduction and lets the matrix product use the tensor pipeline.  The vendor
    eigensolver returns the eigenvectors as a column-major view, so the caller
    passes the element strides instead of assuming a contiguous tile.
    """
    batch = tl.program_id(0)
    lane = tl.arange(0, BLOCK_N)
    lane_mask = lane < n

    input_offsets = (
        batch * stride_batch + lane[:, None] * stride_row + lane[None, :] * stride_col
    )
    matrix_mask = lane_mask[:, None] & lane_mask[None, :]
    eigenvectors_tile = tl.load(
        eigenvectors + input_offsets, mask=matrix_mask, other=0.0
    )
    eigenvalues_tile = tl.load(
        eigenvalues + batch * n + lane, mask=lane_mask, other=0.0
    )
    sqrt_eigenvalues = tl.sqrt(tl.maximum(eigenvalues_tile, 0.0))

    scaled_eigenvectors = eigenvectors_tile * sqrt_eigenvalues[None, :]
    result = tl.dot(scaled_eigenvectors, tl.trans(eigenvectors_tile))
    # Hermitian projection, matching ATen's post-processing.
    result = 0.5 * (result + tl.trans(result))
    output_offsets = batch * n * n + lane[:, None] * n + lane[None, :]
    tl.store(output + output_offsets, result, mask=matrix_mask)


