def _fused_matrix_sqrth(inp, eigenvalues, eigenvectors, output=None):
    n = inp.shape[-1]
    batch_count = eigenvectors.numel() // (n * n)
    stride_row = eigenvectors.stride(-2)
    stride_col = eigenvectors.stride(-1)
    stride_batch = eigenvectors.stride(-3) if eigenvectors.dim() > 2 else n * n
    if output is None:
        output = torch.empty(
            (batch_count, n, n), dtype=eigenvectors.dtype, device=eigenvectors.device
        )
    block_n = max(triton.next_power_of_2(n), 16)
    with torch_device_fn.device(eigenvectors.device):
        _sqrt_reconstruct_kernel[(batch_count,)](
            eigenvectors,
            eigenvalues,
            output,
            n,
            stride_batch,
            stride_row,
            stride_col,
            BLOCK_N=block_n,
        )
    return output.reshape(inp.shape)


