    logger.debug("GEMS_ENFLAME LINALG_MATRIX_SQRTH")
    _validate_input(inp)

    if inp.shape[-1] == 0:
        return inp.clone()

    # ATen reads only the lower triangle (UPLO="L") and assumes that it
    # describes a symmetric/Hermitian positive-definite matrix.
